  #region Enums
  /// <summary>
  /// Complete census of visible, deconstructible non-player buildings touching Home.
  /// Absence of roof_blocker means safe removal.
  /// </summary>
  public enum ClearanceClass {
    [pbr::OriginalName("CLEARANCE_CLASS_UNSPECIFIED")] Unspecified = 0,
    [pbr::OriginalName("CLEARANCE_CLASS_ANCIENT_WALL_DOOR")] AncientWallDoor = 1,
    [pbr::OriginalName("CLEARANCE_CLASS_SHIP_CHUNK")] ShipChunk = 2,
    [pbr::OriginalName("CLEARANCE_CLASS_ANCIENT_CASKET")] AncientCasket = 3,
    [pbr::OriginalName("CLEARANCE_CLASS_OTHER")] Other = 4,
  }

  /// <summary>
  /// Ancient shrines: each sealed or opened ancient-danger room as one
  /// unit. Caskets report native hit points and HasAnyContents; the occupant
  /// stays unknown until opened. Guards are the hostile pawns and hives inside
  /// the room rectangle and are complete only once the interior is unfogged.
  /// Breach walls are the perimeter walls the player may deconstruct without
  /// a roof-support blocker, each with the adjacent cell outside the room.
  /// </summary>
  public enum ShrineGuardKind {
    [pbr::OriginalName("SHRINE_GUARD_KIND_UNSPECIFIED")] Unspecified = 0,
    [pbr::OriginalName("SHRINE_GUARD_KIND_MECHANOID")] Mechanoid = 1,
    [pbr::OriginalName("SHRINE_GUARD_KIND_INSECTOID")] Insectoid = 2,
    [pbr::OriginalName("SHRINE_GUARD_KIND_FLESHBEAST")] Fleshbeast = 3,
    [pbr::OriginalName("SHRINE_GUARD_KIND_HUMAN")] Human = 4,
    [pbr::OriginalName("SHRINE_GUARD_KIND_HIVE")] Hive = 5,
    [pbr::OriginalName("SHRINE_GUARD_KIND_OTHER")] Other = 6,
  }

  public enum SurgeryKind {
    [pbr::OriginalName("SURGERY_KIND_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Installs a part where the body part is missing.
    /// </summary>
    [pbr::OriginalName("SURGERY_KIND_RESTORE")] Restore = 1,
    /// <summary>
    /// Removes a condition.
    /// </summary>
    [pbr::OriginalName("SURGERY_KIND_CURE")] Cure = 2,
    /// <summary>
    /// Removes a damaged or artificial part.
    /// </summary>
    [pbr::OriginalName("SURGERY_KIND_AMPUTATE")] Amputate = 3,
    /// <summary>
    /// Installs over a present part, or an implant.
    /// </summary>
    [pbr::OriginalName("SURGERY_KIND_INSTALL")] Install = 4,
    /// <summary>
    /// Removes a clean natural part.
    /// </summary>
    [pbr::OriginalName("SURGERY_KIND_HARVEST")] Harvest = 5,
    /// <summary>
    /// Any other medical recipe (administer, execute).
